import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.BefGvJmu.js";const u=JSON.parse('{"title":"Contributing","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md"}'),o={name:"contributing.md"};function r(s,e,c,d,l,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Build and run the project using <a href="/pai-website/guide/installation.html">Installation</a>. Keep each change focused on a documented behavior. For a bug fix, add a case that reproduces the failure and verify it after the fix.</p><h2 id="specification-changes" tabindex="-1">Specification changes <a class="header-anchor" href="#specification-changes" aria-label="Permalink to &quot;Specification changes&quot;">​</a></h2><p>Include a concrete request/response exchange or file sample, the expected behavior, and the effect on existing files and clients. Update the relevant specification, schemas, fixtures, and implementation together.</p><p>Keep normative requirements in <code>spec/</code>. Use the BCP 14 keywords defined in the <a href="/pai-website/spec/#conformance-language">specification overview</a> for requirements that can be checked by an implementer. Put reference implementation choices and usage examples in the integration guides. An implementation detail becomes a protocol requirement only through an explicit specification change.</p><h2 id="code-and-verification" tabindex="-1">Code and verification <a class="header-anchor" href="#code-and-verification" aria-label="Permalink to &quot;Code and verification&quot;">​</a></h2><p>After installing both dependency trees, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>This builds the editor and runs file, specification, and current service tests. For browser or editor behavior, also run the <a href="https://github.com/JacenDu/pai-protocol/blob/main/development/acceptance/README.md" target="_blank" rel="noreferrer">browser acceptance workflow</a> and describe the interaction checked. Report the environment, commands, results, and any checks not run.</p><p>Maintain the original image bytes and document identity when a change only converts file packaging. Preserve existing publication snapshots when changing current publication behavior. Add compatibility cases for changes to file parsing, hashes, retries, or historical reads.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>The default README, specifications, API guides, code comments, and release notes use professional technical English. Keep <a href="https://github.com/JacenDu/pai-protocol/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">README.zh-CN.md</a> aligned with the default README when scope, setup, or status changes. Chinese sample content, product UI, and product notes may remain Chinese. Diagram labels use English.</p><p>Use the established <a href="/pai-website/spec/terminology.html">terminology</a>. Describe observable behavior with precise inputs, outputs, and error conditions. Label examples and implementation choices clearly. Do not add marketing claims, unmeasured performance claims, or new terminology for an existing concept.</p><p>Test handoff, acceptance workflows, and development records belong in <code>development/</code>. Keep historical reports unchanged and add a new record for a new run. An independent acceptance result is recorded by the tester; developer checks do not fill that report.</p><h2 id="pull-requests-and-licensing" tabindex="-1">Pull requests and licensing <a class="header-anchor" href="#pull-requests-and-licensing" aria-label="Permalink to &quot;Pull requests and licensing&quot;">​</a></h2><p>State the problem, the resulting behavior, and the validation performed. Link the affected specification sections and describe any compatibility change. Include dependency and license updates when adding a package.</p><p>Contributions are submitted under the project&#39;s <a href="/pai-website/LICENSE.txt">Apache-2.0 license</a>. Preserve third-party attributions. Keep service credentials, private published content, and local runtime data out of commits.</p>',17)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
